template:
@php
    $look = in_array($tone, ['surface', 'accent', 'image'], true) ? $tone : 'plain';
    $picture = $look === 'image' && is_array($image) && ! empty($image['url']) ? $image : null;
@endphp
@if ($title || $subtitle)
<section @class(['b-hero', 'b-hero--'.$look, 'b-hero--center' => $align === 'center', 'site-bleed' => $width === 'bleed']) data-wx-block="hero">
    @if ($picture)
        <img class="b-hero__picture" src="{{ $picture['url'] }}" alt="{{ $picture['alt'] ?? '' }}" @if (! empty($picture['width'])) width="{{ $picture['width'] }}" height="{{ $picture['height'] }}" @endif>
    @endif
    @if ($look === 'image')
        <div class="b-hero__shade"></div>
    @endif
    <div class="b-hero__inner">
        @if ($title)
            <h1 class="b-hero__title">{{ $title }}</h1>
        @endif
        @if ($subtitle)
            <p class="b-hero__subtitle">{{ $subtitle }}</p>
        @endif
        @if (($button_label && $button_url) || ($second_label && $second_url))
            <div class="b-hero__actions">
                @if ($button_label && $button_url)
                    <a class="b-hero__button" href="{{ $button_url }}">{{ $button_label }}</a>
                @endif
                @if ($second_label && $second_url)
                    <a class="b-hero__button b-hero__button--quiet" href="{{ $second_url }}">{{ $second_label }}</a>
                @endif
            </div>
        @endif
    </div>
</section>
@endif

styles:
.b-hero {
    --hero-ring: var(--site-color-accent);
    container-type: inline-size;
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding-block: var(--site-space-7);
    color: var(--site-color-text);
}

.b-hero--surface,
.b-hero--accent,
.b-hero--image {
    border-radius: var(--site-radius-lg);
}

.b-hero.site-bleed {
    border-radius: 0;
}

.b-hero--surface {
    background: var(--site-color-surface-muted);
}

.b-hero--accent {
    --hero-ring: var(--site-color-accent-contrast);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
}

/* Over a picture the words are the page's background on a shade of its text: they read on any
   picture, and the night preset turns both round together. */
.b-hero--image {
    --hero-ring: var(--site-color-bg);
    display: flex;
    align-items: flex-end;
    min-height: 22rem;
    background: var(--site-color-text);
    color: var(--site-color-bg);
}

.b-hero__picture {
    position: absolute;
    inset: 0;
    z-index: -2;
    width: 100%;
    max-width: none;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

.b-hero__shade {
    position: absolute;
    inset: 0;
    z-index: -1;
    background: linear-gradient(to top, color-mix(in srgb, var(--site-color-text) 85%, transparent), color-mix(in srgb, var(--site-color-text) 45%, transparent));
}

.b-hero__inner {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--site-space-4);
    width: 100%;
    max-width: var(--site-container-width);
    margin-inline: auto;
    padding-inline: var(--site-space-5);
}

/* On the page itself the words keep to the column's left edge, like the text under them. */
.b-hero--plain .b-hero__inner {
    padding-inline: 0;
}

.b-hero.site-bleed .b-hero__inner {
    padding-inline: var(--site-gutter);
}

.b-hero--center .b-hero__inner {
    align-items: center;
    text-align: center;
}

.b-hero__title {
    max-width: 22em;
    margin: 0;
    color: inherit;
    font-family: var(--site-font-heading);
    font-size: var(--site-font-size-2);
    line-height: 1.1;
    hyphens: auto;
}

.b-hero__subtitle {
    max-width: 40em;
    margin: 0;
    font-size: var(--site-font-size-5);
}

.b-hero--plain .b-hero__subtitle,
.b-hero--surface .b-hero__subtitle {
    color: var(--site-color-text-muted);
}

.b-hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
    margin-top: var(--site-space-2);
}

.b-hero--center .b-hero__actions {
    justify-content: center;
}

.b-hero--accent .b-hero__button:not(.b-hero__button--quiet) {
    background: var(--site-color-accent-contrast);
    color: var(--site-color-accent);
}

.b-hero__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0 var(--site-space-5);
    border: 1px solid transparent;
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: background-color var(--site-duration) var(--site-easing), color var(--site-duration) var(--site-easing);
}

.b-hero__button:hover {
    background: color-mix(in srgb, var(--site-color-accent) 85%, var(--site-color-text));
}

.b-hero__button:focus-visible {
    outline: 2px solid var(--hero-ring);
    outline-offset: 2px;
}

.b-hero__button--quiet,
.b-hero__button--quiet:hover {
    border-color: currentColor;
    background: transparent;
    color: inherit;
}

@container (min-width: 40rem) {
    .b-hero {
        padding-block: var(--site-space-8);
    }

    .b-hero__inner {
        padding-inline: var(--site-space-7);
    }

    .b-hero__title {
        font-size: var(--site-font-size-1);
    }

    .b-hero--image {
        min-height: 30rem;
    }
}
